@app.cell
def _(pd):
    file = pd.read_csv(
        "/home/pushkar/computational_materials_learning/"
        "data/l2_stability.csv"
    )

    numeric_columns = [
        "exponent",
        "naive",
        "stable",
        "reference",
    ]

    for column in numeric_columns:
        file[column] = pd.to_numeric(
            file[column],
            errors="coerce",
        )

    file.head()
    return (file,)


@app.cell
def _(file, np):
    # Extract benchmark quantities.
    exponent = file["exponent"].to_numpy()
    naive = file["naive"].to_numpy()
    stable = file["stable"].to_numpy()
    reference = file["reference"].to_numpy()

    # Relative errors with respect to the analytical solution.
    stable_relative_error = (
        np.abs(stable - reference) / np.abs(reference)
    )

    # Only calculate the naive relative error where the naive result
    # is finite. At the extremes it deliberately becomes 0 or inf.
    naive_relative_error = np.full_like(
        naive,
        np.nan,
        dtype=float,
    )

    valid_naive = (
        np.isfinite(naive)
        & (naive > 0.0)
        & np.isfinite(reference)
        & (reference > 0.0)
    )

    naive_relative_error[valid_naive] = (
        np.abs(
            naive[valid_naive]
            - reference[valid_naive]
        )
        / np.abs(reference[valid_naive])
    )
    return naive_relative_error, stable_relative_error


